  function buildClassicalPilaster(parent, x, z, width, botY, topY, rotY, terraMat, trimMat) {
    const g = new Group();
    g.position.set(x, 0, z);
    g.rotation.y = rotY;
    const totalH = topY - botY;
    const baseH = 0.52;
    const capH = 0.72;
    const shaftH = totalH - baseH - capH;
    const shaftMidY = botY + baseH + shaftH * 0.5;
    const basePlinth = new Mesh(new BoxGeometry(width + 0.16, 0.28, 0.28), trimMat);
    basePlinth.position.set(0, botY + 0.14, 0.1);
    g.add(basePlinth);
    const baseTorus = new Mesh(new BoxGeometry(width + 0.08, 0.24, 0.22), terraMat);
    baseTorus.position.set(0, botY + 0.4, 0.09);
    g.add(baseTorus);
    const shaft = new Mesh(new BoxGeometry(width, shaftH, 0.18), terraMat);
    shaft.position.set(0, shaftMidY, 0.07);
    shaft.castShadow = true;
    shaft.receiveShadow = true;
    g.add(shaft);
    const panelCount = 5;
    const segH = shaftH / panelCount;
    const innerPanelW = width * 0.62;
    for (let i = 0; i < panelCount; i++) {
      const py2 = botY + baseH + (i + 0.5) * segH;
      const panelInset = new Mesh(new BoxGeometry(innerPanelW, segH - 0.22, 0.05), trimMat);
      panelInset.position.set(0, py2, 0.155);
      g.add(panelInset);
    }
    const capY = topY - capH * 0.5;
    const capBell = new Mesh(new BoxGeometry(width + 0.1, capH * 0.72, 0.26), terraMat);
    capBell.position.set(0, capY - 0.06, 0.11);
    capBell.castShadow = true;
    g.add(capBell);
    const abacus = new Mesh(new BoxGeometry(width + 0.24, capH * 0.28, 0.34), trimMat);
    abacus.position.set(0, topY - capH * 0.14, 0.14);
    abacus.castShadow = true;
    g.add(abacus);
    [-width * 0.36, 0, width * 0.36].forEach((lx, idx) => {
      const leaf = new Mesh(
        new BoxGeometry(width * 0.22, capH * 0.52, 0.1),
        trimMat
      );
      leaf.position.set(lx, capY - 0.04, 0.24);
      g.add(leaf);
      if (idx !== 1) {
        const volute = new Mesh(
          new CylinderGeometry(0.11, 0.11, 0.12, 10),
          trimMat
        );
        volute.rotation.x = Math.PI * 0.5;
        volute.position.set(lx * 1.15, topY - 0.22, 0.25);
        g.add(volute);
      }
    });
    parent.add(g);
  }
