    shaft.position.y = 0.91;
    shaft.castShadow = true;
    g.add(shaft);
    const capCollar = new Mesh(new CylinderGeometry(0.12, 0.08, 0.1, 8), ironMat);
    capCollar.position.y = 1.54;
    g.add(capCollar);
    const glassHead = new Mesh(new CylinderGeometry(0.19, 0.13, 0.44, 4), frostedGlassMat);
    glassHead.rotation.y = Math.PI * 0.25;
    glassHead.position.y = 1.81;
    g.add(glassHead);
    for (let i = 0; i < 4; i++) {
      const ang = i / 4 * Math.PI * 2 + Math.PI * 0.25;
      const rib = new Mesh(new BoxGeometry(0.024, 0.46, 0.024), ironMat);
      rib.position.set(Math.cos(ang) * 0.155, 1.81, Math.sin(ang) * 0.155);
      g.add(rib);
    }
    const roofRim = new Mesh(new CylinderGeometry(0.23, 0.23, 0.04, 4), ironMat);
    roofRim.rotation.y = Math.PI * 0.25;
    roofRim.position.y = 2.05;
